"use client";

import type { CSSProperties, ReactNode } from "react";
import type { AomiClientOptions } from "@aomi-labs/react";
import { AomiFrame, type AomiFrameControlBarProps } from "./aomi-frame";
import { AomiWalletKitProvider, useAomiWalletKit } from "../lib/wallet-kit";
import type {
  AuthConfig,
  ProvidersConfig,
  WalletsConfig,
} from "../lib/wallet-kit/config/types";
import { BackendAaProvider } from "../lib/wallet-kit/execution/backend-aa-context";
import { BackendAaProvisioner } from "./backend-aa-provisioner";

export type CrossOriginWidgetAuth =
  | { kind: "browser_wallet" }
  | {
      kind: "embedded_wallet";
      provider: "para";
      environment: string;
      /** Para public project key. Cross-origin hosts must pass it here; only
       * Next-style hosts that inline `NEXT_PUBLIC_PARA_API_KEY` may omit it. */
      apiKey?: string;
    }
  | {
      kind: "embedded_wallet";
      provider: "privy";
      environment?: string;
      /** Privy public app ID. Same contract as Para's `apiKey`. */
      appId?: string;
    };

export type WalletPresentationConfig = WalletsConfig;

export type AomiWidgetProps = {
  children?: ReactNode;
  applicationId: string;
  apiUrl: string;
  width?: CSSProperties["width"];
  height?: CSSProperties["height"];
  className?: string;
  style?: CSSProperties;
  walletPosition?: "header" | "footer" | null;
  walletFamilies?: Array<"evm" | "solana">;
  showSidebar?: boolean;
  showHeader?: boolean;
  controlBarProps?: Omit<AomiFrameControlBarProps, "children">;
  clientOptions?: Omit<AomiClientOptions, "baseUrl" | "getAccountBearer">;
  persistThread?: boolean;
  threadPersistenceKey?: string;
  threadPersistenceScope?: string | null;
  initialThreadId?: string;
  auth: CrossOriginWidgetAuth;
  wallets?: WalletPresentationConfig;
};

export function AomiWidget(props: AomiWidgetProps) {
  const resolvedApiUrl = props.apiUrl.replace(/\/+$/, "");
  const resolved = resolveWidgetAuth(props.auth);
  const account = {
    mode: "aomi-backend" as const,
    baseUrl: resolvedApiUrl,
    widgetAuth:
      props.auth.kind === "embedded_wallet"
        ? {
            mode: "provider" as const,
            provider: props.auth.provider,
            // Privy's exchange accepts only PROD; Para carries its own value.
            environment: props.auth.environment ?? "PROD",
          }
        : { mode: "wallet" as const },
  };

  return (
    <AomiWalletKitProvider
      auth={resolved.auth}
      providers={resolved.providers}
      wallets={props.wallets}
      execution={{ aa: "off", sponsorship: { mode: "disabled" } }}
      account={account}
    >
      <WidgetFrame
        apiUrl={resolvedApiUrl}
        applicationId={props.applicationId}
        width={props.width}
        height={props.height}
        className={props.className}
        style={props.style}
        walletPosition={props.walletPosition}
        walletFamilies={props.walletFamilies}
        showSidebar={props.showSidebar}
        showHeader={props.showHeader}
        controlBarProps={props.controlBarProps}
        clientOptions={props.clientOptions}
        persistThread={props.persistThread}
        threadPersistenceKey={props.threadPersistenceKey}
        threadPersistenceScope={props.threadPersistenceScope}
        initialThreadId={props.initialThreadId}
      />
      {props.children}
    </AomiWalletKitProvider>
  );
}

type WidgetFrameProps = Pick<
  AomiWidgetProps,
  | "width"
  | "height"
  | "className"
  | "style"
  | "walletPosition"
  | "walletFamilies"
  | "showSidebar"
  | "showHeader"
  | "controlBarProps"
  | "clientOptions"
  | "persistThread"
  | "threadPersistenceKey"
  | "threadPersistenceScope"
  | "initialThreadId"
> & { apiUrl: string; applicationId: string };

function WidgetFrame({
  apiUrl,
  applicationId,
  width = "100%",
  height = "80vh",
  className,
  style,
  walletPosition = "footer",
  walletFamilies = ["evm", "solana"],
  showSidebar = true,
  showHeader = true,
  controlBarProps,
  clientOptions,
  persistThread,
  threadPersistenceKey,
  threadPersistenceScope,
  initialThreadId,
}: WidgetFrameProps) {
  const walletKit = useAomiWalletKit();
  return (
    <BackendAaProvider
      value={{ apiUrl, getAccountBearer: walletKit.getAccountBearer }}
    >
      <AomiFrame.Root
        key={walletKit.accountUser?.id ?? "anonymous"}
        backendUrl={apiUrl}
        applicationId={applicationId}
        accountSessionAvailable={Boolean(walletKit.accountUser)}
        clientOptions={{
          ...clientOptions,
          getAccountBearer: walletKit.getAccountBearer,
        }}
        width={width}
        height={height}
        className={className}
        style={style}
        walletPosition={walletPosition}
        walletFamilies={walletFamilies}
        showSidebar={showSidebar}
        persistThread={persistThread}
        threadPersistenceKey={threadPersistenceKey}
        threadPersistenceScope={threadPersistenceScope}
        initialThreadId={initialThreadId}
      >
        <BackendAaProvisioner applicationId={applicationId} />
        {showHeader ? (
          <AomiFrame.Header showSidebarTrigger={showSidebar} />
        ) : null}
        <AomiFrame.Composer
          withControl
          controlBarProps={{
            hideApiKey: true,
            hideNetwork: false,
            ...controlBarProps,
          }}
        />
      </AomiFrame.Root>
    </BackendAaProvider>
  );
}

function resolveWidgetAuth(auth: CrossOriginWidgetAuth): {
  auth: AuthConfig;
  providers?: ProvidersConfig;
} {
  if (auth.kind === "browser_wallet") return { auth: false };
  if (auth.provider === "para") {
    return {
      auth: { provider: "para" },
      providers: {
        para: {
          apiKey: auth.apiKey,
          environment:
            auth.environment.toUpperCase() === "PROD" ? "PROD" : "BETA",
        },
      },
    };
  }
  return {
    auth: { provider: "privy" },
    providers: { privy: { appId: auth.appId } },
  };
}

"use client";

import { useEffect } from "react";
import { useAomiRuntime } from "@aomi-labs/react";
import { useAomiWalletKit } from "../lib/wallet-kit";
import { useBackendAa } from "../lib/wallet-kit/execution/backend-aa-context";

export function BackendAaProvisioner({
  applicationId,
}: {
  applicationId: string;
}) {
  const { currentThreadId } = useAomiRuntime();
  const wallet = useAomiWalletKit();
  const backend = useBackendAa();
  const owner = wallet.identity.address;
  const chainId = wallet.identity.chainId;
  const numericApplicationId = Number(applicationId);

  useEffect(() => {
    if (
      !owner ||
      !chainId ||
      !wallet.accountUser ||
      !backend.getAccountBearer ||
      // A non-numeric applicationId would serialize as `null` in the PUT body
      // while the GET query still carries the raw string — the two calls would
      // then disagree on the application identity. Skip rather than misprovision.
      !Number.isInteger(numericApplicationId)
    ) {
      if (applicationId && !Number.isInteger(numericApplicationId)) {
        console.warn(
          "[BackendAaProvisioner] applicationId is not a valid integer",
          applicationId,
        );
      }
      return;
    }
    const controller = new AbortController();

    void (async () => {
      const bearer = await backend.getAccountBearer?.();
      if (!bearer || controller.signal.aborted) return;
      const headers = {
        authorization: `Bearer ${bearer}`,
        "x-thread-id": currentThreadId,
      };
      const query = new URLSearchParams({
        application_id: applicationId,
        chain_id: String(chainId),
        owner,
      });
      const profileResponse = await fetch(
        `${backend.apiUrl}/api/widget/v1/execution-profile?${query}`,
        { credentials: "omit", headers, signal: controller.signal },
      );
      if (!profileResponse.ok) return;
      const profile = (await profileResponse.json()) as {
        accountStatus?: string;
      };
      if (profile.accountStatus === "active" || controller.signal.aborted)
        return;
      await fetch(`${backend.apiUrl}/api/widget/v1/aa-accounts/${chainId}`, {
        method: "PUT",
        credentials: "omit",
        headers: { ...headers, "content-type": "application/json" },
        body: JSON.stringify({ applicationId: numericApplicationId, owner }),
        signal: controller.signal,
      });
    })().catch((error) => {
      if (!controller.signal.aborted) {
        console.warn("[BackendAaProvisioner] provisioning unavailable", error);
      }
    });

    return () => controller.abort();
  }, [
    applicationId,
    numericApplicationId,
    backend.apiUrl,
    backend.getAccountBearer,
    chainId,
    currentThreadId,
    owner,
    wallet.accountUser,
  ]);

  return null;
}
